<?php
declare(strict_types=1);
require_once __DIR__.'/../../lib/helpers.php';send_cors_headers();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);$body=get_json_body();$email=strtolower(trim((string)($body['email']??'')));$password=(string)($body['password']??'');if(!is_valid_email($email)||$password==='')json_response(422,['success'=>false,'message'=>'Enter email and password.']);$stmt=get_db()->prepare('SELECT * FROM influencers WHERE email=:email');$stmt->execute(['email'=>$email]);$creator=$stmt->fetch();if(!$creator||!password_verify($password,$creator['password_hash'])){if(rate_limit('influencer-login|'.$email.'|'.request_ip(),10,900))json_response(429,['success'=>false,'message'=>'Too many sign-in attempts.']);json_response(401,['success'=>false,'message'=>'Sign-in details are incorrect.']);}if(!$creator['email_verified'])json_response(403,['success'=>false,'message'=>'Verify your email first.']);if(in_array($creator['status'],['suspended','blocked','inactive'],true))json_response(403,['success'=>false,'message'=>'Creator account is restricted.']);$session=create_auth_session('influencer',$creator['id'],filter_var($body['remember']??false,FILTER_VALIDATE_BOOL));get_db()->prepare('UPDATE influencers SET last_login_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$creator['id']]);audit_event('influencer.login','influencer',$creator['id']);json_response(200,['success'=>true,'message'=>'Signed in.','csrf_token'=>$session['csrf_token'],'influencer'=>['id'=>$creator['id'],'full_name'=>$creator['full_name'],'email'=>$creator['email'],'handle'=>$creator['handle'],'status'=>$creator['status'],'verification_status'=>$creator['verification_status']]]);
